function prixTtc(prixHt, taux) {
  const montantTaxe = prixHt * taux;
  return Math.round((prixHt + montantTaxe) * 100) / 100;
}
const total = prixTtc(10, 0.2);
console.log(total); // 12

function prixTtcIncorrect(prixHt, taux) {
  console.log(prixHt * (1 + taux));
}
console.log(prixTtcIncorrect(10, 0.2)); // affiche 12 puis undefined
